pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Fund the caller with enough ether for two lockInGuess calls
        vm.deal(address(this), 3 ether);
        // First lockInGuess should succeed
        bytes32 hash1 = keccak256("guess1");
        c.lockInGuess{value: 1 ether}(hash1);
        // Attempt a second lockInGuess with the same address
        bytes32 hash2 = keccak256("guess2");
        bool ok;
        try c.lockInGuess{value: 1 ether}(hash2) {
            ok = true;
        } catch {
            ok = false;
        }
        // Reference version reverts (ok == false), buggy version succeeds (ok == true)
        // Assert that the call reverted
        assertTrue(!ok);
    }
}

